mapper.insert:
INSERT INTO amount (
    requested_amount, approved_amount, requested_at, approved_at,
    created_at, status, amount_comment, workcation_no
) VALUES (
    #{requestedAmount}, #{approvedAmount}, NOW(), #{approvedAt},
    NOW(), COALESCE(#{status}, 'R'), #{amountComment}, #{workcationNo}
)

INSERT INTO amount_item (
    item_type, item_date, item_approved, item_description, amount_no
) VALUES (
    #{itemType}, COALESCE(#{itemDate}, NOW()), #{itemApproved}, #{itemDescription}, #{amountNo}
)

INSERT INTO amount_list (
    amount_no, sponsor_name, amount, payment_date, status, remark, item_no
) VALUES (
    #{amountNo}, #{sponsorName}, #{amount}, COALESCE(#{paymentDate}, NOW()), 
    COALESCE(#{status}, 'UNPAID'), #{remark}, #{itemNo}
)

INSERT INTO amount_file (
    file_path, origin_name, change_name, updated_at, status, amount_no
) VALUES (
    #{filePath}, #{originName}, #{changeName}, NOW(), 'Y', #{amountNo}
)

